  --danger: #ef4444;
  --danger-hover: #dc2626;
  --danger-glow: rgba(239, 68, 68, 0.25);
  --shadow: 0 20px 50px rgba(0, 0, 0, 0.55), 0 8px 16px rgba(0, 0, 0, 0.35);
  --radius: 14px;
  --radius-sm: 8px;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Inter, Roboto,
    "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

body {
  background:
    radial-gradient(1200px 600px at 20% -10%, rgba(106, 169, 255, 0.08), transparent 60%),
    radial-gradient(900px 500px at 110% 10%, rgba(239, 68, 68, 0.06), transparent 60%),
    var(--bg);
}

.app {
  max-width: 880px;
  margin: 0 auto;
  padding: 48px 24px 80px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28px;
  color: var(--text-muted);
  font-size: 14px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--text);
  font-weight: 600;
  letter-spacing: 0.2px;
}

.brand-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: linear-gradient(135deg, #6aa9ff, #b06aff);
  box-shadow: 0 0 12px rgba(106, 169, 255, 0.6);
}

.crumbs span + span::before {
  content: "/";
  margin: 0 8px;
  color: var(--text-dim);
}

.preview-card {
  background: linear-gradient(180deg, var(--bg-elev), #11151a);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: var(--shadow);
}

.preview-image {
  position: relative;
  aspect-ratio: 16 / 10;
  background: #0a0c0f;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.preview-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.preview-image::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 60%, rgba(0, 0, 0, 0.45));
  pointer-events: none;
}

.preview-meta {
  padding: 18px 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-top: 1px solid var(--border);
  background: var(--bg-elev-2);
}

.meta-text h1 {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.1px;
}

.meta-text p {
  margin: 0;
  font-size: 13px;
  color: var(--text-muted);
}

.actions {
  display: flex;
  gap: 10px;
}

.btn {
  appearance: none;
  border: 1px solid var(--border-strong);
  background: var(--bg-elev);
  color: var(--text);
  padding: 9px 14px;
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease,
    transform 0.05s ease, box-shadow 0.15s ease, color 0.15s ease;
}

.btn:hover {
  background: #1f252c;
  border-color: #3a4350;
}

.btn:active { transform: translateY(1px); }

.btn:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--bg), 0 0 0 4px var(--accent);
}

.btn .icon {
  width: 16px;
  height: 16px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.btn-danger {
  color: #ffb4b4;
  border-color: rgba(239, 68, 68, 0.35);
  background: rgba(239, 68, 68, 0.08);
}

.btn-danger:hover {
  color: #fff;
  background: rgba(239, 68, 68, 0.18);
  border-color: rgba(239, 68, 68, 0.55);
}

.btn-danger-solid {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
  box-shadow: 0 6px 20px var(--danger-glow);
}

.btn-danger-solid:hover {
  background: var(--danger-hover);
  border-color: var(--danger-hover);
}

/* ---------- Modal ---------- */

.modal-overlay {
  position: fixed;
  inset: 0;
  background: rgba(4, 6, 9, 0.65);
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
  opacity: 0;
  animation: fadeIn 0.18s ease forwards;
}

.modal {
  width: 100%;
  max-width: 440px;
  background: linear-gradient(180deg, #181d24, #12161b);
  border: 1px solid var(--border-strong);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 24px;
  transform: translateY(8px) scale(0.98);
  opacity: 0;
  animation: popIn 0.2s cubic-bezier(0.2, 0.8, 0.2, 1) forwards;
}

.modal-header {
  display: flex;
  gap: 14px;
  align-items: flex-start;
  margin-bottom: 14px;
}

.modal-icon {
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  border-radius: 50%;
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ff8a8a;
}

.modal-icon svg {
  width: 20px;
  height: 20px;
  stroke: currentColor;
  fill: none;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.modal-title {
  margin: 2px 0 0;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: 0.1px;
}

.modal-body {
  color: var(--text-muted);
  font-size: 14px;
  line-height: 1.55;
  margin: 0 0 20px;
}

.modal-body strong { color: var(--text); font-weight: 600; }

.modal-footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@keyframes fadeIn {
  to { opacity: 1; }
}

@keyframes popIn {
  to { transform: translateY(0) scale(1); opacity: 1; }
}

@media (max-width: 520px) {
  .preview-meta { flex-direction: column; align-items: stretch; }
  .actions { justify-content: flex-end; }
}
